// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0); // plain EOA: low-level call to it succeeds
        amount = bound(amount, 1, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // first withdrawal must succeed: contract holds exactly `amount`
        vm.prank(actor);
        bool ok1; try c.withdrawAll() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first withdrawal should succeed");
        assertEq(address(c).balance, 0, "contract drained after first withdrawal");

        // RULE: once fully withdrawn, a repeated withdrawAll by the same actor
        // must NOT revert (credit is zero in the correct contract).
        vm.prank(actor);
        bool ok2; try c.withdrawAll() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "repeated withdrawAll after full withdrawal must not revert");
    }
}
